UPDATE so_historical_event SET impacts_json=replace(impacts_json, '"FactionId":4', '"FactionId":13')
 WHERE code='evt_184_khan_vang' AND NOT EXISTS (SELECT 1 FROM core_state WHERE key='date');
UPDATE so_historical_event SET impacts_json=(SELECT json_group_array(json(value)) FROM json_each(impacts_json)
 WHERE json_extract(value,'$.Kind')!='city_owner') WHERE code='evt_200_quan_do_dai_chien'
 AND NOT EXISTS (SELECT 1 FROM core_state WHERE key='date');
UPDATE so_historical_event SET impacts_json=replace(impacts_json,'Tào Ngụy','Tào Tháo'), narrative_vi=replace(narrative_vi,'Tào Ngụy','Tào Tháo'), title_vi=replace(title_vi,'Tào Ngụy','Tào Tháo'), rumor_title_vi=replace(rumor_title_vi,'Tào Ngụy','Tào Tháo'), rumor_narrative_vi=replace(rumor_narrative_vi,'Tào Ngụy','Tào Tháo') WHERE year<220 AND NOT EXISTS (SELECT 1 FROM core_state WHERE key='date');
UPDATE so_historical_event SET impacts_json=replace(impacts_json,'Thục Hán','Lưu Bị'), narrative_vi=replace(narrative_vi,'Thục Hán','Lưu Bị'), title_vi=replace(title_vi,'Thục Hán','Lưu Bị'), rumor_title_vi=replace(rumor_title_vi,'Thục Hán','Lưu Bị'), rumor_narrative_vi=replace(rumor_narrative_vi,'Thục Hán','Lưu Bị') WHERE year<221 AND NOT EXISTS (SELECT 1 FROM core_state WHERE key='date');
UPDATE so_historical_event SET impacts_json=replace(impacts_json,'Đông Ngô','Tôn Quyền'), narrative_vi=replace(narrative_vi,'Đông Ngô','Tôn Quyền'), title_vi=replace(title_vi,'Đông Ngô','Tôn Quyền'), rumor_title_vi=replace(rumor_title_vi,'Đông Ngô','Tôn Quyền'), rumor_narrative_vi=replace(rumor_narrative_vi,'Đông Ngô','Tôn Quyền') WHERE year>=200 AND year<229 AND NOT EXISTS (SELECT 1 FROM core_state WHERE key='date');
UPDATE so_historical_event SET impacts_json=replace(impacts_json,'"NpcCode":"npc_0018"','"NpcCode":null')
 WHERE code='evt_184_khan_vang' AND NOT EXISTS (SELECT 1 FROM core_state WHERE key='date');
